def choose_move(observation):
    x, y = observation['self_position']
    width, height = observation['grid_width'], observation['grid_height']
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    opponent_pos = observation.get('opponent_position', None)

    def dist(a, b):
        return abs(a[0] - b[0]) + abs(a[1] - b[1])

    target = None
    min_d = float('inf')
    for r in resources:
        p = r
        d = dist((x, y), p)
        if d < min_d:
            min_d = d
            target = p
    if not target and opponent_pos:
        d = dist((x, y), opponent_pos)
        if d < min_d:
            min_d = d
            target = opponent_pos
    if not target:
        return [0, -1]  # default move: up

    dx = dy = 0
    if target[0] > x: dx = 1
    elif target[0] < x: dx = -1
    if target[1] > y: dy = 1
    elif target[1] < y: dy = -1

    new_x = x + dx
    new_y = y + dy
    if (new_x, new_y) in obstacles or not (0 <= new_x < width and 0 <= new_y < height):
        if dx != 0:
            dx = 0
            new_x = x
            new_y = y + (1 if dy >= 0 else -1)
            if (new_x, new_y) in obstacles or not (0 <= new_x < width and 0 <= new_y < height):
                if dy != 0:
                    dy = 0
        if dx == 0 and dy == 0:
            return [0, 0]
    return [dx, dy]
